import{_ as l,C as i,o,c as h,j as n,a as c,E as r,a2 as a}from"./chunks/framework.CQjSGuJt.js";const k=JSON.parse('{"title":"Level editor (spec)","description":"","frontmatter":{},"headers":[],"relativePath":"guide/editor.md","filePath":"guide/editor.md"}'),s={name:"guide/editor.md"};function d(g,t,u,m,p,v){const e=i("Badge");return o(),h("div",null,[t[0]||(t[0]=n("h1",{id:"level-editor-spec",tabindex:"-1"},[c("Level editor (spec) "),n("a",{class:"header-anchor",href:"#level-editor-spec","aria-label":'Permalink to "Level editor (spec)"'},"​")],-1)),r(e,{type:"tip",text:"Live"}),t[1]||(t[1]=a(` Đã build theo spec này. Mở: <code>npm run dev</code> rồi vào <code>http://localhost:8080/editor/</code>; bản đăng ở <code>&lt;pagesUrl&gt;/editor/</code>.<h2 id="cach-dung-nhanh" tabindex="-1">Cách dùng nhanh <a class="header-anchor" href="#cach-dung-nhanh" aria-label="Permalink to &quot;Cách dùng nhanh&quot;">​</a></h2><ul><li><strong>Nơi lưu:</strong> mở lần đầu, editor tự dùng <strong>Browser storage</strong> và nạp sẵn toàn bộ level của game (chỉ nằm trong trình duyệt đó). Muốn sửa level của game thì bấm <strong>Choose folder</strong> và trỏ vào thư mục <code>level-data/</code> của project (Chrome / Edge); folder trống sẽ được nạp sẵn level của game.</li><li>Nút <strong>★</strong> ở panel Levels: thêm các level của game còn thiếu (không ghi đè level đang có).</li><li><strong>Phím tắt:</strong> V chọn · P sửa ống · 1–8 cọ màu · 0 tẩy · R xoay · D nhân bản · Del xoá · Ctrl+Z / Ctrl+Y · Ctrl+S lưu · Space chơi thử · Esc bỏ chọn / thoát chơi thử.</li><li><strong>Ống (P):</strong> kéo điểm, bấm ⊕ để thêm điểm, bấm đúp điểm để xoá. Điểm vàng là điểm bắt đầu.</li><li><strong>Cổng:</strong> chấm xanh = tự động, vàng = đặt tay; kéo chấm dọc ống để đặt tay.</li><li>Sau khi sửa level, vào <strong>Organiser</strong> bấm <strong>Save collection</strong> để cập nhật bản copy trong <code>collections/Main/</code> (game đọc từ đó).</li></ul><p>Editor là một trang riêng trong cùng project Vite + TypeScript, chạy ở <code>&lt;pagesUrl&gt;/editor/</code> (cạnh <code>/demo/</code> và <code>/docs/</code>). Editor <strong>không</strong> nằm trong bản snapshot của từng version (<code>build_demo</code> / <code>release_demo</code>).</p><h2 id="_1-du-lieu-level" tabindex="-1">1. Dữ liệu level <a class="header-anchor" href="#_1-du-lieu-level" aria-label="Permalink to &quot;1. Dữ liệu level&quot;">​</a></h2><p>Theo <a href="./../gdd/level-format">GDD: Level format</a>.</p><ul><li><strong>Ống:</strong> đa giác bo góc (<code>cornerRadius</code>), cá chạy theo thứ tự điểm. Khép kín, hoặc <strong>hở có 2 cổng</strong> (<code>open</code>, có nút bật/tắt; cá qua cổng tức thì). <code>inlet</code> / <code>outlet</code> chỉ để trang trí (ống khép kín). 6 mẫu ống: Chữ nhật, Chữ nhật nhỏ, Chữ L, Chữ U, Chữ T ngược, Lục giác; thêm mẫu &quot;Chữ U hở 2 cổng&quot;.</li><li><strong>Thông số:</strong> <code>pipeSpeed</code> (px/s), <code>slotLength</code> (quyết định sức chứa ống), <code>fishPerUnit</code>, <strong>N</strong> <code>pipeLimit</code> (số nấc tối đa trên ống cùng lúc, mặc định 5), <strong>cỡ xe</strong> <code>busScale</code> (theo từng level, mặc định 1).</li><li><strong>Xe:</strong> x, y, xoay 0/90/180/270, <strong>sức chứa cố định 4 nấc</strong> (không chỉnh trong editor), các nấc màu (đầu → đuôi xe), cổng tự động hoặc đặt tay.</li><li><strong>Vị trí xe dự phòng</strong> (<code>spareSlots</code>) cho booster Thêm xe: mỗi level ít nhất 1. Nút <strong>+ Dự phòng</strong> tự tìm chỗ trống (hết chỗ thì báo: dời xe, giảm cỡ xe hoặc Tự xếp xe); vẫn kéo tay được. Level mới tạo có sẵn 1 vị trí.</li><li><strong>Booster:</strong> số lượt Undo / Shuffle / Thêm xe. Cùng với <code>goal</code>, <code>seed</code>.</li><li><strong>Bảng màu:</strong> 8 màu: red, yellow, green, blue, purple, orange, pink, cyan.</li><li>Khung thiết kế 1080 × 1920.</li><li>Không có chướng ngại hay xe đặc biệt. Không có dữ liệu ngoài level (tiền tệ, tiến trình) mà editor phải tránh.</li></ul><h3 id="canh-bao" tabindex="-1">Cảnh báo <a class="header-anchor" href="#canh-bao" aria-label="Permalink to &quot;Cảnh báo&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mức</th><th>Điều kiện</th></tr></thead><tbody><tr><td>Lỗi</td><td>Ống không hợp lệ</td></tr><tr><td>Lỗi</td><td>Ống chứa ít hơn 2 nấc</td></tr><tr><td>Lỗi</td><td>Chưa có xe nào</td></tr><tr><td>Lỗi</td><td>Số nấc của một màu không vừa khít bất kỳ nhóm xe nào</td></tr><tr><td>Lỗi</td><td>Tổng nấc lớn hơn tổng chỗ trên xe</td></tr><tr><td>Lỗi</td><td><code>pipeSpeed</code> quá lớn so với <code>slotLength</code></td></tr><tr><td>Lỗi</td><td><code>pipeLimit</code> (N) lớn hơn sức chứa ống</td></tr><tr><td>Lỗi</td><td>Xe có số nấc vượt sức chứa</td></tr><tr><td>Cảnh báo</td><td>Xe đã hoàn thành ngay từ đầu</td></tr><tr><td>Cảnh báo</td><td>Hai xe chồng lên nhau</td></tr><tr><td>Lỗi</td><td>Xe / vị trí dự phòng đè lên ống nước</td></tr><tr><td>Lỗi</td><td>Chưa có vị trí xe dự phòng (booster Thêm xe cần ít nhất 1)</td></tr><tr><td>Cảnh báo</td><td>Vị trí dự phòng chồng lên xe</td></tr><tr><td>Lỗi</td><td>Vị trí dự phòng không nối thẳng vào ống (đuôi xe không hướng ra ống hoặc bị xe khác chắn)</td></tr><tr><td>Cảnh báo</td><td>Số booster Thêm xe lớn hơn số vị trí xe dự phòng</td></tr><tr><td>Thông tin</td><td>Chưa có <code>goal</code></td></tr></tbody></table><h2 id="_2-sinh-level" tabindex="-1">2. Sinh level <a class="header-anchor" href="#_2-sinh-level" aria-label="Permalink to &quot;2. Sinh level&quot;">​</a></h2><p>Giữ nguyên ống và vị trí xe, chỉ rải lại màu.</p><ul><li><strong>Designer nhập:</strong> số màu (1–8), số xe để trống, độ khó mục tiêu (Dễ / Vừa / Khó).</li><li><strong>Editor tự làm:</strong><ul><li>Mỗi màu <strong>cố định 4 nấc</strong>, xáo ngẫu nhiên rồi rải vào xe.</li><li>Tránh xe đã hoàn thành sẵn.</li><li>Chạy solver tối đa 40 lần cho đến khi được màn giải được đúng độ khó.</li></ul></li><li><strong>Tự xếp xe:</strong> xếp các xe thành một cột ở giữa vùng bên trong ống.</li></ul><h2 id="_3-luu-du-lieu" tabindex="-1">3. Lưu dữ liệu <a class="header-anchor" href="#_3-luu-du-lieu" aria-label="Permalink to &quot;3. Lưu dữ liệu&quot;">​</a></h2><ul><li>Folder trên máy (File System Access API, chỉ Chrome / Edge), hoặc Browser storage.</li><li>Giữ <strong>3 bản cũ</strong> gần nhất của mỗi level.</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;folder&gt;/</span></span>
<span class="line"><span>  levels/&lt;id&gt;.json</span></span>
<span class="line"><span>  levels/.versions/&lt;id&gt;/</span></span>
<span class="line"><span>  drafts/current.json</span></span>
<span class="line"><span>  collections.json</span></span>
<span class="line"><span>  collections/&lt;Tên&gt;/NNN_&lt;id&gt;.json</span></span></code></pre></div><ul><li><strong>Id là số.</strong> Editor tự cấp số tiếp theo khi tạo level mới.</li><li><strong>Import</strong> không ghi đè: id trùng thì đổi sang số trống tiếp theo.</li><li><strong>Xoá</strong> có hỏi xác nhận; lịch sử bản cũ vẫn giữ.</li><li><strong>Đổi id</strong> thì chuyển theo cả file, lịch sử và các collection.</li></ul><h2 id="_4-quan-ly-level" tabindex="-1">4. Quản lý level <a class="header-anchor" href="#_4-quan-ly-level" aria-label="Permalink to &quot;4. Quản lý level&quot;">​</a></h2><ul><li><strong>Thanh thông tin:</strong> Name, Id, Status (WIP / PROD / ARCHIVE), Difficulty (Dễ / Vừa / Khó / Rất khó, tự điền từ solver và sửa tay được), Category (chữ tự do).</li><li><strong>Organiser:</strong> xếp level thành collection có thứ tự chơi. Ban đầu có sẵn collection <strong>Main</strong> chứa 5 level gốc theo thứ tự cũ.</li><li><strong>Add level</strong> mở hộp thoại riêng: <ul><li>Chỉ liệt kê các level chưa có trong collection, mỗi dòng có ô tick.</li><li>Có ô tìm theo tên.</li><li>Hai nút <strong>Add all levels</strong> và <strong>Add selected levels</strong> (mờ khi chưa tick gì), kèm dòng &quot;N of M selected&quot;.</li><li>Level mới được thêm vào cuối collection.</li><li>Nếu mọi level đã có trong collection thì hiện &quot;All levels are already in this collection.&quot;</li><li>Nút X đóng hộp thoại mà không thêm gì.</li></ul></li></ul><h2 id="_5-kiem-tra-level-muc-c" tabindex="-1">5. Kiểm tra level (mức C) <a class="header-anchor" href="#_5-kiem-tra-level-muc-c" aria-label="Permalink to &quot;5. Kiểm tra level (mức C)&quot;">​</a></h2><ul><li>Cảnh báo dữ liệu (mục 1).</li><li>Nút <strong>▶ Play</strong> để chơi thử.</li><li><strong>Mô phỏng:</strong><ul><li>Solver tìm lời giải <strong>nhanh nhất về thời gian chơi</strong> (số lần tap, thời gian) và tự điền <code>goal</code>.</li><li>Cho nhiều người chơi ngẫu nhiên chơi thử, đo tỉ lệ thắng → độ khó: ≥ 40% Dễ, ≥ 15% Vừa, ≥ 5% Khó, &lt; 5% Rất khó.</li><li><em>TBD</em>: với giới hạn N = 5, người chơi ngẫu nhiên gần như luôn thua (0–5%) kể cả ở màn solver giải rất nhanh, nên thang độ khó này cần làm lại (ví dụ đo theo số trạng thái solver phải thử, hoặc người chơi &quot;biết chờ&quot;).</li></ul></li></ul><h2 id="_6-choi-thu" tabindex="-1">6. Chơi thử <a class="header-anchor" href="#_6-choi-thu" aria-label="Permalink to &quot;6. Chơi thử&quot;">​</a></h2><ul><li>Nút <strong>▶ Play</strong> (phím Space) mở game Phaser phủ lên editor với level đang mở, kể cả các thay đổi chưa lưu.</li><li>Game đọc <strong>thẳng file level JSON</strong> của editor, không cần chuyển đổi.</li><li><strong>‹</strong> / Esc để quay lại editor, <strong>↻</strong> để chơi lại.</li><li>Nút <strong>Xem lời giải</strong>: bàn tay hướng dẫn tự chơi màn đang mở theo lời giải của solver.</li></ul><h2 id="_7-giao-dien" tabindex="-1">7. Giao diện <a class="header-anchor" href="#_7-giao-dien" aria-label="Permalink to &quot;7. Giao diện&quot;">​</a></h2><ul><li>Logo Athena (cam ở theme tối, đen ở theme sáng).</li><li>Theme tối / sáng có nút chuyển, lựa chọn được nhớ.</li><li>Bố cục theo mẫu Fish Ball: danh sách level bên trái, vùng làm việc ở giữa, Inspector bên phải. Các panel thu gọn được và kéo đổi kích thước được, trạng thái được nhớ.</li></ul>`,30))])}const x=l(s,[["render",d]]);export{k as __pageData,x as default};
